import { ChangeDetectionStrategy, ChangeDetectorRef, Component } from '@angular/core';
import { FinishedProductInward, FinishedProductInwardService } from '../../services/finished-product-inward-service';
import { Router, RouterLink } from '@angular/router';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'app-finished-product-inward',
  imports: [CommonModule, FormsModule, RouterLink],
  templateUrl: './finished-product-inward.html',
  styleUrl: './finished-product-inward.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class FinishedProductInwardComponent {
Inward: FinishedProductInward[] = [];
  searchTerm = '';
  constructor(private service: FinishedProductInwardService, private cd: ChangeDetectorRef, public router: Router) {}

  ngOnInit() {
    this.service.getInward().subscribe({
      next: (data) => {
        this.Inward = data;
        this.cd.markForCheck();
        console.log("products from backend: ", this.Inward);
      },
      error: (err) => console.error("error fetching inwards: ", err)
    })
  }

FilteredInwards() {
  const term = this.searchTerm.toLowerCase();
  return this.Inward.filter(r =>
    (r.lotNo?.toString() ?? "").includes(term) ||
    (r.productName ?? "").toLowerCase().includes(term) ||
    (r.inwardDate ?? "").toLowerCase().includes(term) ||
    (r.grossQty?.toString() ?? "").includes(term) ||
    (r.bags?.toString() ?? "").includes(term) ||
    (r.perKg?.toString() ?? "").includes(term)
  );
}
}
